/** Measured-data boundary. Source declarations and row holdouts are preserved;
 * a curve-fit validation never implies validated cloth, contact, or production. */
const DIRECTIONS=['warp','weft','shear'];
const aliases={warp:'warp',weft:'weft',shear:'shear','经向':'warp','纵向':'warp','纬向':'weft','横向':'weft','剪切':'shear'};
const clone=x=>JSON.parse(JSON.stringify(x));
function cells(line){const out=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){out.push(value.trim());value='';}else value+=c;}if(quoted)throw new Error('CSV 引号未闭合');out.push(value.trim());return out;}
function number(value,name,row,{min=0,max=Infinity,optional=false}={}){if(optional&&(value==null||value===''))return null;const n=Number(value);if(value===''||value==null||!Number.isFinite(n)||n<min||n>max)throw new Error(`CSV 第 ${row} 行 ${name} 数值无效`);return n;}
export function parseMaterialCSV(text,options={}){
  if(typeof text!=='string'||text.length>2_000_000)throw new TypeError('CSV 内容必须是小于 2 MB 的文本');
  const comments={},lines=[];for(const raw of text.replace(/^\uFEFF/,'').split(/\r?\n/)){const line=raw.trim();if(!line)continue;if(line.startsWith('#')){const m=line.match(/^#\s*(\w+)\s*:\s*(.*)$/);if(m)comments[m[1]]=m[2];}else lines.push(line);}
  const sourceType=options.sourceType||comments.sourceType;if(!['synthetic','measured'].includes(sourceType))throw new Error('必须明确 sourceType: measured 或 synthetic');
  if(comments.sourceType&&comments.sourceType!==sourceType)throw new Error(`文件已声明 ${comments.sourceType}；禁止改标来源`);
  const units={force:'N',length:'m',strain:'ratio',transmittance:'ratio',...options.units};if(units.force!=='N'||units.length!=='m'||units.strain!=='ratio'||units.transmittance!=='ratio')throw new Error('单位必须为 force=N、length=m、strain=ratio、transmittance=ratio');
  if(lines.length<2||lines.length>20001)throw new Error('CSV 必须含表头与 1–20000 条记录');
  const headers=cells(lines[0]).map(x=>x.toLowerCase());if(new Set(headers).size!==headers.length)throw new Error('CSV 表头重复');for(const key of ['direction','strain','forcen','widthm','gaugem'])if(!headers.includes(key))throw new Error(`CSV 缺少 ${key}；只接受 N、m 与无量纲应变`);
  const records=lines.slice(1).map((line,index)=>{const values=cells(line);if(values.length!==headers.length)throw new Error(`CSV 第 ${index+2} 行列数不一致`);const row=Object.fromEntries(headers.map((h,i)=>[h,values[i]]));const direction=aliases[row.direction?.toLowerCase()];if(!direction)throw new Error(`CSV 第 ${index+2} 行方向必须为 warp/weft/shear`);const strain=number(row.strain,'strain',index+2,{max:10}),forceN=number(row.forcen,'forceN',index+2,{max:1e9}),widthM=number(row.widthm,'widthM',index+2,{min:1e-8,max:100}),gaugeM=number(row.gaugem,'gaugeM',index+2,{min:1e-8,max:100});const cycle=row.cycle||'1';if(!/^\d+$/.test(cycle)||Number(cycle)<1||Number(cycle)>100000)throw new Error('cycle 必须为正整数');const split=row.split||'fit';if(!['fit','holdout'].includes(split))throw new Error('split 必须为 fit 或 holdout');return {direction,strain,forceN,widthM,gaugeM,cycle:String(Number(cycle)),split,transmittance:number(row.transmittance,'transmittance',index+2,{max:1,optional:true}),areaStretch:number(row.areastretch,'areaStretch',index+2,{min:1e-8,max:100,optional:true}),tensionNPerM:forceN/widthM};});
  const sampleId=String(options.sampleId||comments.sampleId||'unspecified').trim();if(!sampleId||sampleId.length>200)throw new Error('sampleId 无效');return {schema:'silk-material-data',version:1,sourceType,sampleId,units,records,provenance:{sourceType,sampleId,description:String(options.description||comments.description||''),declaredBy:'importer',recordCount:records.length}};
}
function curve(rows,key){const points=new Map();for(const r of rows){if(r[key]==null)continue;const a=points.get(r.strain)||[];a.push(r[key]);points.set(r.strain,a);}return [...points].map(([strain,a])=>({strain,[key]:a.reduce((x,y)=>x+y,0)/a.length})).sort((a,b)=>a.strain-b.strain);}
function interpolate(points,strain,key){if(points.length===1)return {value:points[0][key],tangent:0,extrapolated:strain!==points[0].strain};let a=points[0],b=points[1];for(let i=1;i<points.length;i++){a=points[i-1];b=points[i];if(strain<=b.strain)break;}const tangent=(b[key]-a[key])/(b.strain-a.strain);return {value:a[key]+(strain-a.strain)*tangent,tangent,extrapolated:strain<points[0].strain||strain>points.at(-1).strain};}
export function evaluateMaterial(profile,direction,strain,{cycle=profile?.fitCycle}={}){
  if(!Number.isFinite(strain))throw new TypeError('应变必须为有限数值');const points=profile?.cycles?.[String(cycle)]?.[direction]||profile?.directionCurves?.[direction];if(!points?.length)return null;
  if(!points.every(p=>Number.isFinite(p.strain)&&Number.isFinite(p.tensionNPerM)))throw new TypeError('材料曲线无效');const r=interpolate(points,Math.max(0,strain),'tensionNPerM');return {tensionNPerM:strain<0?0:Math.max(0,r.value),tangentNPerM:Math.max(1e-8,r.tangent),extrapolated:strain<0||r.extrapolated};
}
export function fitMaterial(data,{relativeTolerance=.15}={}){
  if(data?.schema!=='silk-material-data'||!Array.isArray(data.records)||!data.records.length||!['synthetic','measured'].includes(data.sourceType))throw new TypeError('无效材料数据');if(!(relativeTolerance>0&&relativeTolerance<=1))throw new RangeError('留出验证阈值必须在 0–1');
  const fit=data.records.filter(r=>r.split==='fit'),holdout=data.records.filter(r=>r.split==='holdout'),cycles={};for(const cycle of [...new Set(fit.map(r=>r.cycle))].sort((a,b)=>Number(a)-Number(b))){cycles[cycle]={};for(const direction of DIRECTIONS){const rows=fit.filter(r=>r.direction===direction&&r.cycle===cycle);if(!rows.length)continue;const points=curve(rows,'tensionNPerM');if(points.length<2)throw new Error(`${direction} / cycle ${cycle} 至少需要两个不同应变的拟合点`);if(points.some((p,i)=>i&&p.tensionNPerM<points[i-1].tensionNPerM))throw new Error('当前拉伸律要求同一 cycle 的力随应变不减；加载与卸载需分开建模');cycles[cycle][direction]=points;}}
  const fitCycle=Object.keys(cycles)[0];if(!fitCycle)throw new Error('至少需要一个拟合周期');const profile={schema:'silk-material',version:1,id:`${data.sampleId}:${data.sourceType}`,sampleId:data.sampleId,sourceType:data.sourceType,units:{strain:'ratio',tension:'N/m'},directionCurves:clone(cycles[fitCycle]),cycles,fitCycle,provenance:clone(data.provenance),calibration:{status:data.sourceType==='synthetic'?'synthetic':'fit',scope:'directional-curve-interpolation',physicsValidated:false,missingDirections:DIRECTIONS.filter(d=>!cycles[fitCycle][d]),fitRows:fit.length,validation:{status:'unverified',rows:holdout.length,scope:'declared-row-holdout',relativeTolerance}},optics:{sourceType:data.sourceType,calibrationStatus:'fit',points:fit.filter(r=>r.transmittance!=null).map(r=>({direction:r.direction,strain:r.strain,transmittance:r.transmittance,areaStretch:r.areaStretch,cycle:r.cycle})),validation:{status:'unverified'}},limitations:['Cycles fitted independently; no hysteresis law.','No biaxial, pressure, garment or manufacturing validation.','Extrapolation outside measured strain range is a linear hypothesis.']};
  if(holdout.length){const residuals=[];let unavailable=0;for(const row of holdout){const predicted=evaluateMaterial(profile,row.direction,row.strain,{cycle:row.cycle});if(!predicted||predicted.extrapolated){unavailable++;continue;}residuals.push({direction:row.direction,error:predicted.tensionNPerM-row.tensionNPerM,actual:row.tensionNPerM});}const rmse=Math.sqrt(residuals.reduce((s,r)=>s+r.error*r.error,0)/(residuals.length||1)),scale=Math.max(1,...residuals.map(r=>Math.abs(r.actual))),relativeRMSE=rmse/scale,byDirection={};for(const direction of new Set(residuals.map(r=>r.direction))){const rows=residuals.filter(r=>r.direction===direction),error=Math.sqrt(rows.reduce((s,r)=>s+r.error*r.error,0)/rows.length),scale=Math.max(1,...rows.map(r=>Math.abs(r.actual))),relative=error/scale;byDirection[direction]={rows:rows.length,rmseNPerM:error,relativeRMSE:relative,status:relative<=relativeTolerance?'passed':'failed'};}const status=!unavailable&&residuals.length&&Object.values(byDirection).every(v=>v.status==='passed')?'passed':'failed';Object.assign(profile.calibration.validation,{status,rmseNPerM:rmse,relativeRMSE,unavailable,byDirection,directions:[...new Set(residuals.map(r=>r.direction))]});if(status==='passed'&&data.sourceType==='measured')profile.calibration.status='validated';}
  const opticalHoldout=holdout.filter(r=>r.transmittance!=null),opticalErrors=[];for(const r of opticalHoldout){const points=curve(fit.filter(f=>f.direction===r.direction&&f.cycle===r.cycle),'transmittance');if(points.length>=2){const v=interpolate(points,r.strain,'transmittance');if(!v.extrapolated)opticalErrors.push(v.value-r.transmittance);}}if(opticalHoldout.length){const rmse=Math.sqrt(opticalErrors.reduce((s,x)=>s+x*x,0)/(opticalErrors.length||1));profile.optics.validation={status:opticalErrors.length===opticalHoldout.length&&rmse<=.05?'passed':'failed',rows:opticalHoldout.length,rmse};if(profile.optics.validation.status==='passed')profile.optics.calibrationStatus=data.sourceType==='measured'?'validated':'synthetic';}return profile;
}
